insert(i,text) { checkInsertRange(i); const [a,b]=split(root,i);
 publish(join(join(a,buildBalancedBoundedChunks(text)),b)); }
deleteRange(i,m) { checkRange(i,m); const [a,tail]=split(root,i);
 const [,b]=split(tail,m); publish(join(a,b)); }
join(a,b) { if(!a)return b; if(!b)return a;
 if(h(a)>h(b)+1) return rebalance(a.left, join(a.right,b));
 if(h(b)>h(a)+1) return rebalance(join(a,b.left), b.right);
 return node(a,b); }
publish(candidate) { const old=root; root=candidate; version++;
 retired.push({version, nodes: onlyIn(old,candidate)});   // reference counts or epochs in practice
 reclaim(); }
reclaim() { const oldest=Math.min(version, ...pinnedVersions);
 for (const r of retired) if (r.version<=oldest) free(r.nodes); }   // never while an older root is pinned
read(snapshot,i) { checkReadRange(snapshot,i); let n=snapshot.root; while(!n.leaf) {
 if(i<n.left.count)n=n.left; else {i-=n.left.count; n=n.right;} }
 return scalarAt(n.chunk,i); }

count(n) = n ? n.count : 0;                          // O(1): cached field
repair(n) = count(n.left) + n.width + count(n.right);  // reads two cached children
merge(a,b) { if(!a)return b; if(!b)return a;
 if(a.priority<=b.priority) return copy(a,{right:merge(a.right,b)},repair);
 return copy(b,{left:merge(a,b.left)},repair); }
insert(i,s) { const [a,b]=splitByCount(root,i); publish(merge(merge(a,buildChunks(s)),b)); }
deleteRange(i,m) { const [a,t]=splitByCount(root,i); const [gone,b]=splitByCount(t,m);
 publish(merge(a,b)); retireAfterOlderPins(gone); }   // gone is still reachable from older roots
